INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-71ce-afde-0440f9dadd89', N'019fa37a-8e57-75fb-91d5-8bfba36d9a81', N'المؤسسة العامة للري', N'المؤسسة العــامة للــري مؤسسة حكــومية عـــامة استحـدثت بموجب قــرار مجلس الـوزراء رقم (542) 26 / 08 / 1438هـ لتحل محل هيئة الري والصرف بالأحساء التي أنشئت ع...', N'المؤسسة العامة للري
المؤسسة العــامة للــري مؤسسة حكــومية عـــامة استحـدثت بموجب قــرار مجلس الـوزراء رقم (542) 26 / 08 / 1438هـ لتحل محل هيئة الري والصرف بالأحساء التي أنشئت عام 1392هـ لإدارة أعمال تشغيل وصيانة الري والصرف بالأحساء، حيث تتسم المؤسسة بشخصيتها االاعتبارية، والاستقلال​ الإداري والمالي، وترتبط ارتباطًا وثيقًا بوزارة البيئة والمياه والزراعة، وتتولى إدارة نشاط الري في عموم المملكة، وتقوم بتشغيله، وتطويره، وتنقل إليها جميع المسؤوليات، والمهام​ المتعلقة بالري، وتسعى بجدية لتحقيق أهدافها الاستراتيجية، وتطوير​ قطاع الري والمياه المجددة والسدود في المملكة. وتتبنى المؤسسة رؤية طموحة تهدف إلى استدامة الموارد المائية، وتحسين كفاءة الاستخدام، والحفاظ على الموارد الطبيعية. يأتي ذلك في إطار تعزيز استخدام المياه غير التقليدية والاستفادة من مياه السدود وتوسيع نطاقها لتلبية احتياجات القطاعات الزراعية والصناعية والحضرية. كما تعمل المؤسسة على تطوير البنية التحتية لشبكة المياه وتحسين جودتها، مع التركيز على الابتكار وتبني أنظمة الري الحديثة، والتحسين المستمر، وتعزيز فعاليتها، وكفاءتها.
الأدوار
​ تعزيز استدامة الموارد المائية بتشغيل وإدارة السدود وشبكات المياه، وتزويد القطاعات الزراعية والصناعية والحضرية بالمياه.
التحسين المستمر لمستوى جودة المياه وتغطية شبكة المياه عبر جميع أرجاء المملكة، والتأكد من مطابقتها للمعايير المحلية والدولية.​
​تقديم مبادرات تدريبية لتعزيز استدامة إنتاج المزارع الصغيرة.
الإسهام الاقتصادي بتحسين البنية التحتية لشبكة نقل وتوزيع المياه والسدود.​​
​توعية العملاء بالاستخدامات المفيدة للمياه السطحية والمجددة وغيرها من الموارد المائية.​
وضع معايير سلامة صارمة لإدارة السدود وشبكات نقل وتوزيع المياه، وتطوير استراتيجيات إدارة السدود.​
الرؤية
التميز في إدارة وتطوير قطاعات الري، وإعادة​ استخدام المياه المجددة والسدود؛ لتحقيق​ الاستدامة.
الرسالة
التوسع باستخدام موارد المياه المستدامة عن طريق تطوير شبكة متكاملة؛ لنقل المياه، وتوزيعها​ بالاعتماد على تقنيات جديدة؛ لتعزيز​ الكفاءة الحقلية، وضمان توفير إمدادات مياه آمنة ومستمرة لجميع القطاعات
