INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e56-7359-9bde-1e154d62da79', N'019fa37a-8e56-7c49-bf66-909ad5fe3f71', N'المنصة الوطنية الموحدة للتوظيف', N'نؤمن في الهيئة السعودية للمياه بأن الكوادر البشرية هي المحرك الأساسي للإنجاز والتميز؛ لذلك نسعى إلى استقطاب أفضل الكفاءات لتحقيق أهدافنا الاستراتيجية لتطوير قطاع المياه؛ سعيًا إلى تحقيق رؤية 2030، في بيئة عمل ملهمة تعزز الاستدامة والابتكار.', N'نؤمن في الهيئة السعودية للمياه بأن الكوادر البشرية هي المحرك الأساسي للإنجاز والتميز؛ لذلك نسعى إلى استقطاب أفضل الكفاءات لتحقيق أهدافنا الاستراتيجية لتطوير قطاع المياه؛ سعيًا إلى تحقيق رؤية 2030، في بيئة عمل ملهمة تعزز الاستدامة والابتكار.
التوظيف
يمكنكم الاطلاع والتقديم على الفرص الوظيفية لدى الهيئة السعودية للمياه عبر
المنصة الوطنية الموحدة للتوظيف (جدارات)', N'المنصة الوطنية الموحدة للتوظيف', N'نؤمن في الهيئة السعودية للمياه بأن الكوادر البشرية هي المحرك الأساسي للإنجاز والتميز؛ لذلك نسعى إلى استقطاب أفضل الكفاءات لتحقيق أهدافنا الاستراتيجية لتطوير قطاع المياه؛ سعيًا إلى تحقيق رؤية 2030، في بيئة عمل ملهمة تعزز الاستدامة والابتكار.', 'ar', NULL)
