INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7c55-a01b-22e394be959f', N'019fa37a-8e57-7d00-9f4b-66d9302a4396', N'سياسة البيانات المفتوحة', N'تُوفر الهيئة السعودية للمياه بيانات مفتوحة لجميع مستخدمي البوابة الإلكترونية بهدف تعزيز الوعي، وتشجيع المشاركة، والاطلاع على الخدمات وسياسات استخدام البيانات. جميع البيانات المتوفرة ذات طابع توعوي وغير ربحي، وتُنشر بشفافية انسجامًا مع رؤية المملكة 2030.', N'ماهي البيانات المفتوحة
هي بيانات متاحة لجميع مستخدمي البوابة الإلكترونية، تهدف إلى تعزيز المشاركة ورفع مستوى المعرفة، والاطلاع على الخدمات وسياسة استخدام تلك البيانات لمعرفة أي تحديثات تتم عليها، وأن جميع البيانات المفتوحة المتوفرة على البوابة الإلكترونية للهيئة توعوية وغير ربحية.
مستخدمو البيانات المفتوحة
يمكن لمستخدمي البوابة الاطلاع على البيانات المفتوحة، كما أن لهم الحق في استخدام هذه البيانات على مسؤوليتهم الشخصية، وهذا الحق مكفول لكافة المستفيدين.
مسؤولية مستخدمي البيانات
يكون مستخدم البيانات المفتوحة مسؤولاً عن إعادة استخدام البيانات في البوابة الإلكترونية للهيئة، ولا يجب أن ينتج عن إعادة استخدام هذه البيانات أي أخطاء تتعلق بمحتوى البيانات ومصدرها وتاريخها.
مسؤولية الهيئة
إن الهيئة غير مسؤولة عن أي ضرر أو سوء استخدام تتعرض له الجهات نتيجة استخدام البيانات المنشورة عبر بوابتها الإلكترونية. كما أنها لا تضمن استمرارية توافر هذه البيانات أو جزء منها، ولا تتحمل الهيئة أي مسؤولية تجاه مستخدمي هذه البيانات، وما قد يقع عليهم من ضرر أو خسارة بسبب إعادة استخدامها.
شروط إعادة الاستخدام
يجب على المستفيد عدم تحريف هذه البيانات أو مصدرها.
يجب ‌ألا تستخدم هذه البيانات في أغراض سياسية أو لدعم نشاط غير مشروع أو إجرامي أو في تعليقات عنصرية أو تمييزية أو التأجيج أو التأثير السلبي في الثقافة أو المساواة أو التحريض أو أي نشاط غير نظامي أو مخالف لعادات المملكة وتقاليدها.
يجب الإشارة إلى مصدر المعلومات التي تم إعادة استخدامها عن طريق وضع رابط البوابة الإلكترونية للهيئة السعودية للمياه للمحافظة على الملكية الفكرية للبيانات ومصداقيتها وصحة مصدرها.
سياسة البيانات المفتوحة مستمدة من سياسات حوكمة البيانات الوطنية الصادر عن الهيئة السعودية للبيانات والذكاء الاصطناعي لمزيد من التفاصيل حول المبادئ الرئيسية والقواعد العامة للبيانات المفتوحة والمبادئ الرئيسية والقواعد العامة لحرية المعلومات
اضغط هنا', N'سياسة البيانات المفتوحة', N'تُوفر الهيئة السعودية للمياه بيانات مفتوحة لجميع مستخدمي البوابة الإلكترونية بهدف تعزيز الوعي، وتشجيع المشاركة، والاطلاع على الخدمات وسياسات استخدام البيانات. جميع البيانات المتوفرة ذات طابع توعوي وغير ربحي، وتُنشر بشفافية انسجامًا مع رؤية المملكة 2030.', 'ar', NULL)
GO
