INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7501-a569-3a66262476cc', N'019fa37a-8e57-7c4c-b006-80c40ae42d9e', N'لمحة عن البيانات المفتوحة', N'أطلقت الهيئة السعودية للمياه منصة البيانات المفتوحة عبر بوابتها الإلكترونية، لتتيح للمستخدمين إمكانية استخدام البيانات المنشورة والاستفادة منها. وتحتوي المنصة على قائمة من الملفات المتعددة التي تشمل مختلف أنواع البيانات ويمكن تحميلها بعدة صيغ مختلفة.', N'أطلقت الهيئة السعودية للمياه منصة البيانات المفتوحة عبر بوابتها الإلكترونية، لتتيح للمستخدمين إمكانية استخدام البيانات المنشورة والاستفادة منها. وتحتوي المنصة على قائمة من الملفات المتعددة التي تشمل مختلف أنواع البيانات ويمكن تحميلها بعدة صيغ مختلفة.', N'لمحة عن البيانات المفتوحة', N'أطلقت الهيئة السعودية للمياه منصة البيانات المفتوحة عبر بوابتها الإلكترونية، لتتيح للمستخدمين إمكانية استخدام البيانات المنشورة والاستفادة منها. وتحتوي المنصة على قائمة من الملفات المتعددة التي تشمل مختلف أنواع البيانات ويمكن تحميلها بعدة صيغ مختلفة.', 'ar', NULL)
