INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-778f-95cc-54eeb99a6004', N'019fa37a-8e57-71b3-837b-f57166ca3a9c', N'الشركة السعودية لشراكات المياه', N'تأسست الشركة السعودية لشراكات المياه عام 2003م؛ حيث تلعب دور ذراع تخصيص قطاع المياه في طرح مشاريع محطات المياه المحلاة والمنقاة والمعالجة وغير المعالجة وجميع...', N'الشركة السعودية لشراكات المياه
هي كيان رائد في قطاع المياه في المملكة العربية السعودية، تعود ملكيتها إلى وزارة المالية. تأسست الشركة لتواكب رؤية المملكة من خلال تعزيز الشراكة بين القطاعين العام والخاص في مشروعات البنية التحتية من المياه والصرف الصحي ضمن إطار الشراكة بين القطاعين تحت نظام (PPP) .​​
الأدوار
المشتري الرئيس لجميع أنواع المياه بما في ذلك المياه المحلاة، المنقاة، والمعالجة .. وغيرها.​ ​
طرح وإدارة عقود مشاريع المياه، الصرف الصحي، خطوط النقل، الخزن الإستراتيجي، والسدود.​ ​
تقدم الشركة خدمات استشارية متخصصة في مجالات الخصخصة، تطوير المشاريع، وإدارة العقود، ما يساهم في تطوير البنى التحتية.​
الرؤية
نسعى لتحقيق الريادة في مجال توفير المياه باستدامة وموثوقية بالشراكة مع القطاعين العام والخاص.​​​
الرسالة
ضمان شراء المياه، وخدماتها بتكلفة مقبولة من خلال المنافسات الشفافة، مع المحافظة على الاستدامة البيئية، والمالية.​​
