INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e58-7bb6-87df-60bbb35f2c93', N'019fa37a-8e58-7e51-9ce9-fbffa71e4ce8', N'استراتيجية الهيئة السعودية للمياه', N'تستعرض هذه الصفحة الرؤية والرسالة الاستراتيجية لهيئة المياه السعودية. وتبرز التزامنا بالإدارة المستدامة للمياه، والابتكار، والرقابة التنظيمية، والتحسين المستمر لجودة الخدمات، بهدف وضع معيار عالمي في قطاع المياه.', N'التوجهــات الاستراتيجية
