INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e58-79b8-9d21-644a15c39a9f', N'019fa37a-8e58-7468-95a6-9b0766c7592c', N'National Water Strategy', N'This page previews the strategic goals of the Saudi Water Authority, which aim to enhance water resources management, improve water services, and ensure sustainability for future generations.', N'Sector Vision
A sustainable water sector that develops and maintains financial resources, protects the environment, and provides a secure supply, high-quality services, and efficiency that contributes to economic and social development.
Strategic Objectives
The water sector aims to achieve the objectives of the National Water Strategy 2030, which include:​
Ensure continuous access to adequate quantities of safe water in normal and emergency situations.
Improve water demand management across all uses.
Provide high-quality and cost-effective water and wastewater services to ensure affordable pricing.
Preserve water resources and improve their utilization, while maintaining the local environment for the benefit of the Saudi community both now and in the future.
Ensure the competitiveness of the water sector and its positive contribution to the national economy by promoting effective governance, private sector participation, localization of capabilities, and innovation.', N'National Water Strategy', N'This page previews the strategic goals of the Saudi Water Authority, which aim to enhance water resources management, improve water services, and ensure sustainability for future generations.', 'en', NULL)
GO
INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019ff9f1-5d92-70c5-93a9-6506dc50ca28', N'019ff9f1-5d63-71c5-a832-fa63172aec0c', N'Beneficiary Awareness', N'Key services, tools, guides, and awareness materials for beneficiaries of Saudi Water Authority services.', N'The Saudi Water Authority places the interests of beneficiaries at the heart of its strategic priorities, including enhancing service quality, improving the beneficiary experience, protecting beneficiaries'' rights, and ensuring the clarity of service-related procedures. This page brings together key services, tools, guides, and awareness materials to facilitate access to reliable information and make effective use of available digital channels.', NULL, NULL, 'en', N'[{"Body":null,"Heading":"Awareness Materials","Id":"733f75f4-6ac2-4506-b98c-cd3ec70e3828","Intro":"This page features awareness and educational materials published through the Authority\u0027s official channels, supporting public awareness, enhancing understanding of procedures, and promoting the efficient use of water.","Kind":1,"SortOrder":0,"Items":[{"Description":"This campaign raises beneficiaries\u0027 awareness of their rights and the procedures related to the service through awareness messages published by the Authority via its official account.","IconId":null,"Id":"512400f1-4c9e-4126-91f5-ec61abb11206","ImageId":null,"LinkUrl":null,"SortOrder":0,"Title":"Know Your Rights"},{"Description":"This video presents an awareness message highlighting the value of water and the efforts involved in delivering it. The video was published by the Authority through its official account.","IconId":null,"Id":"d349cfa3-6501-4924-8c8d-2f3eb76b7a85","ImageId":null,"LinkUrl":null,"SortOrder":1,"Title":"It Didn\u0027t Come Easy (Majat Bil ssahil)"}]},{"Body":null,"Heading":"Estimation Tools","Id":"b02f72cd-440f-4e07-afab-80266c51a0c7","Intro":"The Authority provides digital support tools that help beneficiaries estimate certain aspects related to water consumption and billing, enabling a better understanding of services and promoting efficient water use.","Kind":1,"SortOrder":1,"Items":[{"Description":"This service enables beneficiaries to estimate expected water consumption based on the entered data related to usage patterns, number of individuals, or type of activity.","IconId":null,"Id":"515b9724-7e91-490d-a2e9-e8103d65ed23","ImageId":null,"LinkUrl":null,"SortOrder":0,"Title":"Water Consumption Estimator"},{"Description":"This service enables beneficiaries to calculate the estimated value of their water bill based on the entered consumption volume.","IconId":null,"Id":"d9606c3d-5441-4268-9314-0e400550fea0","ImageId":null,"LinkUrl":"/services/water-bill-calculator","SortOrder":1,"Title":"Water Bill Calculator"}]},{"Body":null,"Heading":"E-Services","Id":"9a69a623-e794-4fe5-8302-a4bd81e428f3","Intro":"The Authority provides a range of electronic services that enable beneficiaries to take the appropriate action and track the status of their requests through approved digital channels.","Kind":1,"SortOrder":2,"Items":[{"Description":"This service enables beneficiaries to escalate complaints submitted to the Authority if the complaint is closed by the service provider without resolution, or if more than ten (10) working days have passed without action.","IconId":null,"Id":"2867d1b4-1b01-4730-9323-d0d0a3ddaf56","ImageId":null,"LinkUrl":"/services/complaint-escalation","SortOrder":0,"Title":"Complaint Escalation"},{"Description":"This service enables beneficiaries to electronically inquire about the status of complaints submitted to the Saudi Water Authority.","IconId":null,"Id":"5d50664c-e262-4141-ba0d-699fe3cceb06","ImageId":null,"LinkUrl":"/services/complaint-inquiry","SortOrder":1,"Title":"Complaint Inquiry"},{"Description":"This service enables beneficiaries to submit reports regarding violations or non-compliant practices related to the water sector.","IconId":null,"Id":"1612d93c-59f0-44d2-a2de-4223970c5648","ImageId":null,"LinkUrl":"/services/report-violations","SortOrder":2,"Title":"Report Violations"}]},{"Body":null,"Heading":"Guides and Instructions","Id":"ae032cbb-d2d3-452e-8333-2ed9915df270","Intro":"The Authority provides a collection of guides, reference documents, and FAQs through its Regulations, Bylaws, and Decisions pages, helping beneficiaries access approved information and better understand service-related requirements and procedures.","Kind":1,"SortOrder":3,"Items":[{"Description":"This guide outlines procedures related to water and wastewater services.","IconId":null,"Id":"599d1695-f353-40df-aea4-7617bdad0aa8","ImageId":null,"LinkUrl":null,"SortOrder":0,"Title":"Water and Wastewater Services Guide"},{"Description":"This guide explains procedures related to water meter inspection and the verification of meter reading accuracy.","IconId":null,"Id":"4a1ed704-61f7-4f4f-93b3-bd12ce43f236","ImageId":null,"LinkUrl":null,"SortOrder":1,"Title":"Water Meter Inspection Guide"},{"Description":"This guide outlines the service requirements, procedures, and related conditions for complaint escalation.","IconId":null,"Id":"ef31537a-d22e-4891-8ab4-7a389044f097","ImageId":null,"LinkUrl":null,"SortOrder":2,"Title":"Complaint Escalation Service Guide"},{"Description":"This page contains answers to frequently asked questions related to services and tools available on the website.","IconId":null,"Id":"fe783a66-1d48-4fed-ba88-0e6b4d84bfe2","ImageId":null,"LinkUrl":null,"SortOrder":3,"Title":"Frequently Asked Questions (FAQs)"}]}]')
