INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e5e-7a13-9666-6be2acb58115', N'019fa37a-8e5e-7743-940c-dbcdcaf0a427', N'طلب موعد لمقابلة معالي رئيس الهيئة السعودية للمياه', N'طلب موعد لمقابلة معالي رئيس الهيئة السعودية للمياه', N'التواصل هو ركيزة أعمالنا، ونسعى دائمًا إلى الارتقاء بجودة آليات التواصل مع المستفيدين في قطاع المياه، ولتعزيز التواصل، تم إتاحة خدمة مقابلة معالي رئيس الهيئة السعودية للمياه، حرصًا على تلقي استفساراتكم واقتراحاتكم بشكل مباشر.', N'طلب موعد لمقابلة معالي رئيس الهيئة السعودية للمياه', N'طلب موعد لمقابلة معالي رئيس الهيئة السعودية للمياه', 'ar', NULL)
