INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e54-73ac-a6fb-6ccc463f7596', N'019fa37a-8e54-71e7-b3e4-2796fa57ce7b', N'نبذة عن الهيئة والتأسيس', N'الصفحة معلومات عنا | الهيئة السعودية للمياه', N'نبذة عـن الهيئة
الهيئة السعودية للمياه هي الجهة المختصة في المملكة بجميع شؤون منظومة المياه على المستويين الإشرافي والتنظيمي، وتقديم الدعم الإستراتيجي للقطاع من خلال الرقابة التنظيمية، والإشراف، وإدارة المياه المستدامة، وتحسين الخدمات، وتعزيز القدرات، والنمو الاقتصادي، والابتكار والتقنية، وحماية البيئة كما تتمتع الهيئة بالشخصية الاعتبارية العامة، والاستقلال المالي والإداري، وترتبط تنظيميًا بمعالي وزير البيئة والمياه والزراعة.​
Your browser does not support the video tag.
التأسيس
تأسست الهيئة السعودية للمياه بموجب قرار مجلس الوزراء رقم (918) بتاريخ 28 /10 /1445هـ، القاضي بالموافقة على تحويل (المؤسسة العامة لتحلية المياه المالحة) إلى هيئة باسم (الهيئة السعودية للمياه)؛ لتكون الجهة المنظِّمة لأنشطة خدمات المياه.​ حيث تتمتع الهيئة بالشخصية الاعتبارية العامة، والاستقلال المالي والإداري، وترتبط تنظيميًّا بمعالي وزير البيئة والمياه والزراعة
رؤيتنا
نموذج عالمي متميز للإدارة المستدامة لخدمات المياه وتمكين الابتكار.
رسالتنا
تحقيق التميز في قطاع المياه من خلال الرقابة التنظيمية، والإشراف، وإدارة المياه المستدامة، وتحسين جودة الخدمات، وتعزيز القدرات، وتحقيق النمو الاقتصادي، والابتكار والتقنية، وحماية البيئة، مع الحفاظ على التزامنا بالمسؤوليات المرحلية خلال مرحلة التحول.
اهدافنا
تهدف الهيئة السعودية للمياه إلى تنظيم الأعمال والخدمات المتعلقة بأنشطة المياه والرقابة عليها وتطوير أساليبها؛ بما يُسهم في تعزيز الاستدامة المالية وتحقيق أهداف رؤية المملكة.
القيـم
المسؤولية
الاستدامة
التكامل و التواصل
الابتكار
مهام الهيئة
وضع المعايير والإجراءات والنماذج ذات الصلة بمجالات اختصاصها.
وضع وتطوير السياسات والخطط والبرامج والمبادرات ذات الصلة بقطاع المياه، والرفع عمّا يتطلب استكمال إجراءات نظامية في شأنه.
وضع الضوابط والاشتراطات اللازمة لما تصدره من تراخيص ذات صلة بالأنشطة المرتبطة بمجالات اختصاصها.
تطوير وتوحيد المعايير الفنية والهندسية المتعلقة بالأنشطة المرتبطة بمجالات اختصاصها، والتحقق من مواءمتها مع معايير ومواصفات المحتوى المحلي ومعايير الاستدامة.
اقتراح مشروعات الأنظمة ذات الصلة بمجالات اختصاص الهيئة، واقتراح تعديل المعمول به منها، والرفع عن ذلك وفقاً للإجراءات النظامية المتبعة.
إدارة وتخطيط متطلبات البنية التحتية لمشروعات قطاع المياه.
إدارة عملية تخطيط المحافظ الرأسمالية لسلسلة إمداد المياه في المملكة، ورفع التقارير والتوصيات والحلول الاستراتيجية والفنية للأداء العام لقطاع المياه.
احتساب مقدار العجز الناتج عن الفرق بين الدخل المفترض للخدمات -الذي تقدره بناءً على أسس تجارية- والدخل الحقيقي المتحقق من التعريفة المعتمدة للسنة المعنية، وتقوم وزارة المالية بسداد ذلك العجز بالاتفاق مع المجلس ووفق النموذج المعتمد في هذا الشأن.
توطين الصناعة والخدمات المتصلة بالأنشطة المرتبطة بمجالات اختصاصها، ورفع نسبة المحتوى المحلي فيها.
تنظيم ورقابة قطاع المياه، من خلال دراسة وإقرار التكاليف والأسعار البينية المرتبطة بتقديم خدمات المياه في المملكة.
تنظيم الاتفاقيات التجارية مع الجهات ذات العلاقة بقطاع المياه.
وضع إطار تنظيمي لخدمات المياه بالتنسيق مع المؤسسات والجهات ذات العلاقة والمرخص لهم؛ لوضع الإطار التنظيمي والإجرائي اللازم لضمان مزاولة جميع أنشطة خدمات المياه -بصفة عامة- سواء للاستخدام العام أو الخاص عند مستويات ذات جودة وموثوقية عالية، وتوفير هذه الخدمات للمستهلك بأسعار وتعريفات مناسبة ومساندة للتنمية المستدامة.
الإشراف والرقابة على تطبيق مواصفات وضوابط جودة المياه والأصول التشغيلية والخدمات المرتبطة بهذه الأصول.
اعتماد المواصفات الفنية والهندسية للأصول التشغيلية لمزودي الخدمة على جميع سلاسل إمداد المياه.
إبرام الاتفاقيات ومذكرات التفاهم ذات الصلة بقطاع المياه مع الجهات المعنية داخل المملكة وخارجها، وفقاً للإجراءات النظامية المتبعة.
عقد المؤتمرات والندوات وجلسات العمل والفعاليات ذات الصلة بنشاط الهيئة داخل المملكة وخارجها، والاشتراك فيها، وفقاً للإجراءات النظامية المتبعة.
دعم البحوث والدراسات وإجراؤها في مجالات اختصاصها، سواء بشكل منفرد أو بالاشتراك مع الجهات ذات العلاقة.
التعاون مع مراكز البحوث وبيوت الخبرة على المستويين المحلي والدولي عند الحاجة، بما يسهم في تحقيق أهداف الهيئة.
تقديم الخدمات أو الأعمال أو المبادرات ذات الصلة بمجالات اختصاصها.
إصدار التراخيص والتصاريح المرتبطة بتقديم الخدمات في قطاع المياه.
مراقبة جميع مقدمي الخدمات في قطاع المياه؛ للتأكد من تقيدهم بالأنظمة وتنفيذ شروط وأحكام التراخيص الصادرة لهم.
مراقبة تطبيق معايير الاستدامة البيئية والاجتماعية والحوكمة في قطاع المياه.
تلقي الشكاوى ذات الصلة بمجالات اختصاصها، والتحقيق فيها والبت فيها وفقاً لما تقضي به الأنظمة.
العمل على توفير البيئة الاستثمارية الملائمة في مجالات اختصاصها، بالتنسيق مع الجهات ذات العلاقة.
العمل على زيادة فرص حصول المستهلكين على الإمدادات اللازمة من خدمات المياه، والعمل على التحقق من إيصالها إلى المناطق التي لم تصل إليها.
التأكد من توفير إمدادات مأمونة وموثوقة من المياه يمكن الاعتماد عليها وذات كفاءة عالية.
حماية حقوق المستهلكين والأشخاص المرخص لهم والمستثمرين في تطوير أنشطة تقديم الخدمة.
التخطيط التكاملي لجميع مكونات سلسلة إمدادات المياه وفقاً لخطة العرض والطلب المعتمدة من الوزارة وفقاً للأحكام النظامية ذات الصلة، وإدارة الأمن المائي، وإعداد تقييم شامل لجاهزية وموثوقية البنية التحتية، والإشراف على أصول المصادر المكملة لأمن الإمداد المائي من المصادر الطبيعية والخزن الاستراتيجي.
مراقبة سلسلة الإمداد، وتحليل ورفع كفاءة البيانات والمعلومات المرتبطة بقطاع المياه، ومراقبة تنفيذ أعمال تطوير البنية التحتية.
الإسهام في بناء القدرات لقطاع المياه عبر التدريب والتأهيل، وذلك بالتنسيق مع الجهات التدريبية.
تمثيل المملكة في الهيئات والمنظمات الإقليمية والدولية في مجالات اختصاص الهيئة وفقاً للإجراءات النظامية.', N'نبذة عن الهيئة والتأسيس', N'الصفحة معلومات عنا | الهيئة السعودية للمياه', 'ar', NULL)
GO
INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e56-7790-9cd3-6f9944079a7b', N'019fa37a-8e56-77ea-b064-8757f983d43a', N'Customer Charter', N'The Saudi Water Authority Customer Charter outlines our commitment to transparency, quality, and sustainable excellence in water management services, ensuring the highest standards of service delivery for all beneficiaries.', N'Commitments of the Saudi Water Authority
This charter reflects the Saudi Water Authority’s commitment to the highest standards of transparency, quality, and sustainability. Its digital portal serves as an effective point of engagement with all beneficiaries.
The Authority Commitments to Beneficiaries
A. Support and Assistance:
Beneficiaries can easily access services and receive support through email or via dedicated service sections. The Authority also provides a comprehensive information center, open data services, knowledge materials, and important links such as service-specific FAQs, all designed to ensure a smooth and rich user experience.
B. Privacy and Confidentiality of Information:
In line with its commitment to protecting personal data, the Saudi Water Authority has developed a privacy policy based on the Personal Data Protection Law and its executive regulations. This document outlines the policies and procedures for collecting and processing personal data, including types of data collected, purposes of use, methods of storage and protection, and rules for sharing or disclosing such data.
The Authority is committed to safeguarding the confidentiality and privacy of information, and to empowering individuals with rights related to their personal data in accordance with the highest standards of transparency and reliability.
To view the policy:
https://www.swa.gov.sa/en/privacy-policy
C. Information Transparency:
To enhance transparency and promote knowledge in the water sector, the Saudi Water Authority has established a comprehensive Information Center. It features annual and specialized reports reflecting the state and progress of the water sector, in addition to pioneering research papers that support scientific research and innovation. The center also includes detailed user guides to help beneficiaries navigate the platform and benefit from its services effectively, making it a trusted reference for researchers and stakeholders in the development of Saudi Arabia''s water sector.
Information Center:
https://www.swa.gov.sa/en/reports
D. Communication and Participation Channels:
The Saudi Water Authority places high importance on prompt interaction with beneficiary inquiries and suggestions through its "Contact Us" page and community engagement platforms. A direct channel is also available to communicate with His Excellency the President of the Authority, along with a digital service to request a meeting, reflecting the Authority''s commitment to beneficiary interests, service quality, and operational excellence.
Communication Channels:
https://www.swa.gov.sa/en/communication-channels
Request a Meeting with His Excellency:
https://www.swa.gov.sa/en/request-visit
E-Services Quality Standards
Website response time not exceeding 5 seconds.
Website availability and uptime of 99% or higher.
Compatibility with various devices and platforms, including desktop, mobile, and tablets.
Compliance with international WCAG standards to ensure accessibility for persons with disabilities.
Rights and Responsibilities of Beneficiaries
As part of The Authority commitment to providing the highest level of e-services, beneficiaries are expected to fulfill certain responsibilities to ensure optimal use, including:
Using the portal in accordance with regulations, the usage policy, and the disclaimer.
Reviewing and adhering to the privacy and confidentiality policies.
Following the Authority''s official guidelines and instructions as outlined in the user support pages.
To review the full policies:
https://www.swa.gov.sa/en/use-and-disclaimer
Continuous Improvement and Innovation
The Authority regularly measures beneficiary satisfaction with its services and actively engages users in improvement processes. It also leverages the latest technologies and provides a dedicated platform for community participation, enabling users to contribute to decision-making by submitting meaningful suggestions that enhance the quality of current and future services and projects.
Service Level Agreements and Quality Assurance
The Saudi Water Authority is committed to the continuous enhancement of service quality for website visitors from both individuals and the business sector, by leveraging the latest technologies to automate digital services and deliver them through smart devices in the easiest and fastest ways possible.
Service Level Agreements (SLAs) have been established for each service to guarantee the highest standards of quality and reliability in the delivery of all digital services.', N'Customer Charter', N'The Saudi Water Authority Customer Charter outlines our commitment to transparency, quality, and sustainable excellence in water management services, ensuring the highest standards of service delivery for all beneficiaries.', 'en', NULL)
GO
INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e58-7069-92b5-734d11dec19e', N'019fa37a-8e58-7b09-a987-bf9c00962183', N'علاقات الموردين', N'تسعى الهيئة السعودية للمياه إلى بناء علاقات استراتيجية راسخة مع الموردين، إدراكاً لدورهم كشركاء أساسيين في تحقيق أهدافها. وانطلاقاً من التزامها برؤية المملكة 2030، تدعم الهيئة مبادرات التوطين لتعزيز الاقتصاد المحلي وتوفير فرص عمل للمواطنين. كما تؤمن بأهمية الشراكة الفعّالة والمستدامة لضمان تقديم خدمات عالية الجودة، مع الحرص على الابتكار والتطوير المستمر بما يحقق التنمية المستدامة ويخدم المجتمع بكفاءة وفاعلية.', N'نظرة عامة
تسعى الهيئة السعودية للمياه إلى بناء علاقات استراتيجية راسخة مع الموردين، إدراكاً لدورهم كشركاء أساسيين في تحقيق أهدافها. وانطلاقاً من التزامها برؤية المملكة 2030، تدعم الهيئة مبادرات التوطين لتعزيز الاقتصاد المحلي وتوفير فرص عمل للمواطنين. كما تؤمن بأهمية الشراكة الفعّالة والمستدامة لضمان تقديم خدمات عالية الجودة، مع الحرص على الابتكار والتطوير المستمر بما يحقق التنمية المستدامة ويخدم المجتمع بكفاءة وفاعلية.
إجراءات تسجيل الموُرّدين في الهيئة السعودية للمياه
تتيح الهيئة السعودية للمياه للموردين التسجيل عبر خطوات إلكترونية ميسّرة، تتضمن:
تقديم متطلبات التأهيل
رفع الوثائق المطلوبة والتوقيع على نموذج الإفصاح عن تضارب المصالح.
متطلبات التأهيل للهيئة السعودية للمياه
الموافقة على قواعد السلوك الخاصة بالموردين
الاطلاع على قواعد السلوك الخاصة بالموردين والموافقة على الإقرار أدناه.
وثيقة قواعد السلوك الخاصة بالمُورّدين
