INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7f6e-a0d1-aa05016adb1f', N'019fa37a-8e57-72cf-9cea-9e14c2d8da0e', N'شركة نقل المياه', N'تتم عمليات نقل المياه من مصادرها المختلفة، سواءً كانت محلاة من مياه البحر، أو مستخرجة​ من مصادر طبيعية، عبر أنظمة نقل متقدمة تعتمد على شبكات أنابيب ضخمة صُمّ...', N'شركة نقل المياه
شركة مستقلة مملوكة بالكامل لحكومة المملكة، وتُمثل: اللجنة الإشرافية لتخصيص قطاع البيئة والمياه والزراعة، ويُعدُّ تأسيس الشركة إحدى نتائج برنامج التخصيص لتحقيق رؤية المملكة 2030 من خلال الأهداف الاستراتيجية الوطنية للمياه، وتسعى الشركة لتحقيق ريادة المملكة في مجال نقل وخزن المياه، والمساهمة في ضمان أمنها المائي على المدى الطويل.​
الأدوار
تطوير المشاريع ​
نقل المياه ​
​التصميم الهندسي والإشراف
إمداد المياه ​​
الرؤية
شركة رائدة في نقل المياه بشكل مستدام وموثوق، ملتزمة بتعظيم القيمة للمستفيدين، والشركاء، والمساهمين.​​
الرسالة
تطوير بنية تحتية عالية الجودة؛ لضمان إمدادات مياه آمنة، ومستمرة ذات قيمة اقتصادية، نلتزم بقيمنا، ونحافظ على بيئتنا وسلامتها.​​
