INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e56-7b3f-b601-b09960ecf64f', N'019fa37a-8e56-7b57-ad28-1d11cb20b554', N'سياسة سهولة الوصول للمنصات والخدمات الرقمية', N'في إطار سعي الهيئة السعودية للمياه إلى تعزيز الشمول الرقمي وضمان وصول جميع فئات المجتمع إلى خدماتها الإلكترونية، تولي الهيئة أهمية قصوى لتطبيق أعلى معايير سهولة الاستخدام والوصول الرقمي، وتلتزم الهيئة بتوفير منصات رقمية تمكن المستخدمين من الوصول للخدمات بكل يسر وسهولة بما في ذلك كبار السن والأشخاص ذوي الإعاقة، وذلك امتثالاً للضوابط والمعايير المحلية والعالمية المعتمدة في هذا السياق.', N'المقدمة
في إطار سعي الهيئة السعودية للمياه إلى تعزيز الشمول الرقمي وضمان وصول جميع فئات المجتمع إلى خدماتها الإلكترونية، تولي الهيئة أهمية قصوى لتطبيق أعلى معايير سهولة الاستخدام والوصول الرقمي، وتلتزم الهيئة بتوفير منصات رقمية تمكن المستخدمين من الوصول للخدمات بكل يسر وسهولة بما في ذلك كبار السن والأشخاص ذوي الإعاقة، وذلك امتثالاً للضوابط والمعايير المحلية والعالمية المعتمدة في هذا السياق.
أهداف السياسة
إتاحة الوصول للمنصات والخدمات الرقمية للهيئة السعودية للمياه لجميع المستخدمين.
استخدام التقنيات اللازمة لتوفير سهولة الوصول إلى الخدمات للأشخاص ذوي الإعاقة وكبار السن.
الامتثال للأنظمة المحلية وأفضل الممارسات العالمية، مثل: إرشادات الوصول إلى محتوى الويب (WCAG) 2.1.
نطاق تطبيق السياسة
جميع المنصات والخدمات الرقمية الخارجية التي تخص الهيئة السعودية للمياه.
كافة المستخدمين للمنصات والخدمات الرقمية:
قطاع أفراد (مواطنين ومقيمين).
قطاع أعمال.
العاملين.
المصطلحات والتعاريف
المصطلح
التعريف
الهيئة
الهيئة السعودية للمياه.
المنصات والخدمات الرقمية
هي الحلول التقنية التي تُبنى عليها المنتجات والخدمات الرقمية، وتُقدّم للمستفيدين تجربة رقمية معززة من خلال (البوابات الرقمية أو تطبيقات الأجهزة الذكية). وتتيح المنصة الرقمية لهذه القنوات أن تتصل وتتكامل فيما بينها، كما أنها تتيح تكامل خدماتها مع الخدمات الخارجية الأخرى.
إرشادات WCAG 2.1
معايير دولية تحدد كيفية تصميم محتوى الويب بما يتناسب مع الأشخاص ذوي الإعاقة، بهدف تمكينهم من الوصول للمحتوى بسهولة ودون عوائق.
شات بوت
مساعد افتراضي مدعوم بالذكاء الاصطناعي، صُمم للتفاعل مع المستخدمين بشكل تلقائي والإجابة على استفساراتهم.
الهيئة
الهيئة السعودية للمياه.
المنصات والخدمات الرقمية
هي الحلول التقنية التي تُبنى عليها المنتجات والخدمات الرقمية، وتُقدّم للمستفيدين تجربة رقمية معززة من خلال (البوابات الرقمية أو تطبيقات الأجهزة الذكية). وتتيح المنصة الرقمية لهذه القنوات أن تتصل وتتكامل فيما بينها، كما أنها تتيح تكامل خدماتها مع الخدمات الخارجية الأخرى.
إرشادات WCAG 2.1
معايير دولية تحدد كيفية تصميم محتوى الويب بما يتناسب مع الأشخاص ذوي الإعاقة، بهدف تمكينهم من الوصول للمحتوى بسهولة ودون عوائق.
شات بوت
مساعد افتراضي مدعوم بالذكاء الاصطناعي، صُمم للتفاعل مع المستخدمين بشكل تلقائي والإجابة على استفساراتهم.
تتضمن سياسة الوصول الآتي:
المادة الأولى: المبادئ
تستند سياسة سهولة الوصول للمنصات والخدمات الرقمية إلى المبادئ التالية:
الإدراك:
التأكد من أن جميع المحتويات وعناصر واجهة المستخدم تُعرض بطرق يمكن لجميع المستخدمين إدراكها.
السهولة:
تصميم الواجهات بحيث تكون سهلة الاستخدام ومتوافقة مع أدوات المساعدة.
الفهم:
ضمان أن يكون المحتوى والواجهة سهلة للفهم والتفاعل، بغض النظر عن القدرات الإدراكية للمستخدمين.
المرونة:
مواكبة المحتوى للتطور التكنولوجي من خلال ضمان قابليته للوصول إليه عن طريق مختلف التقنيات المساعدة.
الاستدامة:
التأكد من استدامة المحتوى وإمكانية الوصول له بالتأثر بالتغييرات أو التطورات التي تتم عليه.
المادة الثانية: معايير سهولة الوصول
تلتزم الهيئة السعودية للمياه بالمعايير التالية لتسهيل الوصول:
الامتثال لمستوى AAA من إرشادات WCAG 2.1:
تلتزم جميع الخدمات الرقمية للهيئة بإرشادات الوصول إلى محتوى الويب (WCAG) 2.1 بمستوى AAA لضمان الوصول لجميع الأفراد بما في ذلك كبار السن وذوي الإعاقة.
التوافق مع أدوات المساعدة:
تدعم المنصات والخدمات الرقمية للهيئة مجموعة واسعة من تقنيات المساعدة، بما في ذلك قارئات الشاشة وأدوات التكبير، لضمان تمكين المستخدمين ذوي الإعاقة وكبار السن من التفاعل مع المنصات.
هيكلية المنصات الرقمية:
بناء هيكل واضح وسهل لتسهيل التنقل بين صفحات وشاشات المنصة.
المحادثة باستخدام تقنيات الذكاء الاصطناعي:
يحتوي الموقع على شات بوت تفاعلي وذلك للإجابة على أسئلة واستفسارات المستخدمين حول تقديم الخدمات
اللغات:
تصميم الموقع باللغة العربية واللغة الإنجليزية لسهولة الوصول لجميع فئات المستخدمين
المادة الثالثة: التقنيات المستخدمة
التقنيات المستخدمة لدعم سهولة الوصول:
بدائل النصوص:
توفير بدائل تناسب احتياجات ذوي الإعاقة وتتيح لهم التعرف على المحتويات النصية أو الوسائط المنشورة في المنصة.
التباين العالي:
يجب ضمان نسبة تباين 1:7 لسهولة قراءة النصوص، مما يساعد المستخدمين ذوي الرؤية المنخفضة.
إعادة تحجيم النصوص:
يجب السماح للمستخدمين بإعادة تحجيم النصوص حتى 200٪ دون فقدان المحتوى أو تعطيل الوظائف.
التنقل السهل:
يجب أن يوفر الموقع نظاماً يدعم التصفح باستخدام لوحة المفاتيح لضمان إمكانية الوصول للمستخدمين.
إدخال الصوت:
يجب تمكين البحث الصوتي والتنقل عبر الموقع باستخدام الأوامر الصوتية، لدعم المستخدمين.
المادة الرابعة: التصفح
التصفح من خلال الأجهزة المختلفة:
يجب أن تكون المنصات الرقمية متوافقة مع مختلف الأجهزة، بما في ذلك أجهزة الحاسوب المكتبية والأجهزة اللوحية والهواتف المحمولة.
مسؤولية التطبيق
يتولى قطاع الرقمنة وتقنية الأعمال مسؤولية تطبيق هذه الوثيقة بالتعاون مع الوحدات التنظيمية ذات العلاقة.
المراجعة والتحديث
تراجع هذه الوثيقة مرة واحدة سنوياً أو كلما دعت الحاجة لذلك.', N'سياسة سهولة الوصول للمنصات والخدمات الرقمية', N'في إطار سعي الهيئة السعودية للمياه إلى تعزيز الشمول الرقمي وضمان وصول جميع فئات المجتمع إلى خدماتها الإلكترونية، تولي الهيئة أهمية قصوى لتطبيق أعلى معايير سهولة الاستخدام والوصول الرقمي، وتلتزم الهيئة بتوفير منصات رقمية تمكن المستخدمين من الوصول للخدمات بكل يسر وسهولة بما في ذلك كبار السن والأشخاص ذوي الإعاقة، وذلك امتثالاً للضوابط والمعايير المحلية والعالمية المعتمدة في هذا السياق.', 'ar', NULL)
GO
INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e58-7e9e-b5b7-b37009378d88', N'019fa37a-8e58-7c5e-b83e-a3a2b364d69d', N'حوكمة منظومة المياه', N'تستعرض هذه الصفحة هيكل الحوكمة في قطاع المياه، موضحة الإطار والسياسات التي تضمن الإدارة المستدامة، والرقابة التنظيمية، والمساءلة داخل هيئة المياه السعودية.', N'الاستراتيجية والسياسات
استراتيجية المياه الوطنية
خطة العرض والطلب طويلة المدى
مزيج المياه
سياسات قطاع المياه
حساب موازنة قطاع المياه
