INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e58-796e-92f4-bedca68e3077', N'019fa37a-8e58-797a-b144-1c5925494b9e', N'سياسة الاستخدام وإخلاء المسؤولية', N'توفر الهيئة السعودية للمياه شروط استخدام شاملة، وسياسات خصوصية، وحماية لحقوق الملكية الفكرية لضمان ثقة المستخدمين والامتثال للمعايير العالمية. كون الاستدامة إحدى قيمنا الأساسية، فإننا نتبع خارطة طريق طموحة تتماشى مع رؤية المملكة العربية السعودية 2030، مما يضمن الشفافية والأمان في كل جانب من جوانب عملياتنا.سياسة الاستخدام وإخلاء المسؤولية', N'سياسة الاستخدام
تنص سياسة الاستخدام على أن جميع المستخدمين الذين يصلون إلى الموقع الإلكتروني للهيئة السعودية للمياه، أو يستخدمون​ خدماتها يجب عليهم الالتزام بالشروط والقوانين المحلية. يُحظر استغلال الموقع لأغراض غير قانونية، أو ​ للتعدي على حقوق الغير. أيّ​ استخدام غير مصرح به للمحتويات؛ أو الخدمات ​ المعروضة قد يعرض المستخدم للمساءلة القانونية. تتحمل الهيئة الحق في تعديل، أو تحديث ​ سياسة الاستخدام في أي وقت، وعلى المستخدمين مراجعة السياسة بانتظام؛ للتأكد ​ من الامتثال للشروط.
إخلاء المسؤولية
لا تتحمل الهيئة السعودية للمياه أيّ مسؤولية عن الأضرار المباشرة، أو غير المباشرة​ التي قد تنجم عن استخدام الموقع، أو الخدمات ​ المقدمة. المعلومات المقدمة على الموقع هي لأغراض معلوماتية فقط، ولا يُعتمد عليها في اتخاذ قرارات قانونية أو تجارية. جميع الروابط الخارجية المقدمة في الموقع هي لأغراض تسهيلية، ولا تتحمل الهيئة أيّ مسؤولية عن محتوى، أو سياسات​ المواقع الخارجية. يُنصح المستخدمون بالتأكد من صلاحية ودقة المعلومات قبل اتخاذ أيّ إجراءات.
حدود الاستخدام
تحدد الهيئة السعودية للمياه حدودًا لاستخدام الموقع والخدمات التي تقدمها. يُمنع إعادة إنتاج، أو نشر أيّ​ محتوى من الموقع دون إذن كتابي مسبق. يجب استخدام المعلومات المتاحة على الموقع بشكل شخصي وغير تجاري، ولا يُسمح بتوزيع أو تعديل المحتوى لأغراض تجارية. أيّ محاولة للاختراق، أو التلاعب​ ببيانات الموقع ستُعد مخالفة قانونية، وستتعامل​ الهيئة معها بحزم.', N'سياسة الاستخدام وإخلاء المسؤولية', N'توفر الهيئة السعودية للمياه شروط استخدام شاملة، وسياسات خصوصية، وحماية لحقوق الملكية الفكرية لضمان ثقة المستخدمين والامتثال للمعايير العالمية. كون الاستدامة إحدى قيمنا الأساسية، فإننا نتبع خارطة طريق طموحة تتماشى مع رؤية المملكة العربية السعودية 2030، مما يضمن الشفافية والأمان في كل جانب من جوانب عملياتنا.سياسة الاستخدام وإخلاء المسؤولية', 'ar', NULL)
GO
