INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7258-bd97-dac701ee7dc3', N'019fa37a-8e57-708e-abd1-5166c6fab238', N'طلب مشاركة البيانات', N'تتيح خدمة طلب البيانات للجهات الحصول على مجموعات بيانات محددة لضمان توافر المعلومات اللازمة لدعم النمو والابتكار، مع الامتثال للمتطلبات القانونية والتنظيمية. الوصول إلى البيانات الدقيقة أمر بالغ الأهمية لاتخاذ قرارات مستنيرة.', N'تتيح خدمة مشاركة البيانات الوصول إلى البيانات بهدف دعم الشفافية، وتعزيز التعاون بين الجهات. وتحتوي الصفحة على نموذج طلب مشاركة البيانات يتضمن معلومات مقدم الطلب، نوع البيانات المطلوبة، والغرض من استخدامها، وذلك لتسهيل الوصول البيانات وفقاً لسياسة مشاركة البيانات الصادرة من الهيئة السعودية للبيانات والذكاء الاصطناعي.
