INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7f9c-b1d5-ddc0bf09650e', N'019fa37a-8e57-7f65-b5bd-18596f37003d', N'المحطات التجريبية', N'استكشف المختبرات والمحطات التجريبية في معهد ابتكار تقنيات المياه والأبحاث، حيث يتم التركيز على معالجة المياه وتحلية المياه وتطوير التقنيات المتقدمة.', N'نبذة عن المحطات التجريبية
بروح الابتكار، وانطلاقًا من التحديات البيئية والمائية، تأسس معهد وتيرا ليكون منصة وطنية رائدة على مستوى العالم في أبحاث وتطوير تقنيات المياه والحلول البيئية المستدامة.
وفي سبيل تحقيق هذه الرؤية الطموحة، أنشأ معهد وتيرا بنية تحتية تجريبية متخصصة، تضم مجموعة من المحطات في مدينة الجبيل بالمنطقة الشرقية عام 1407هـ (1987م)، لتكون مركزًا للأبحاث التطبيقية في مجال تحلية المياه.
يمتلك معهد وتيرا خبرات تراكمية وبنية بحثية متقدمة تتيح له دراسة وتقييم مختلف تقنيات المعالجة والتحلية، من خلال نماذج تشغيل تجريبي ومحاكاة دقيقة لأداء الأنظمة والحلول. وتغطي هذه الأعمال مختلف طرق المعالجة وتحلية المياه، إلى جانب اختبار الحلول التقنية لأغراض التقييم العملي، وتطوير نماذج تشغيل مبتكرة، تشمل تقنيات استخلاص المعادن من الرجيع الملحي وغيرها.
وتُعد المحطات التجريبية الذراع التطبيقي الميداني لمعهد وتيرا، حيث تمكّنه من اختبار وتقييم واعتماد المنتجات الصناعية، مثل المواد الكيميائية، والأغشية، والمعدات، والتقنيات الجديدة، لاستخدامها في قطاع المياه بشكل تجاري.
كما تضم المحطات التجريبية وحدات للمعالجة الأولية لمياه البحر، ووحدات "تحلية حرارية" و "تحلية بالتناضح العكسي"، إضافة إلى وحدات الطاقة المتجددة، وفريقًا متخصصًا في التشغيل والصيانة يمتلك القدرة على تعديل وإعادة تصميم الوحدات لتتناسب مع منهجيات الاختبار البحثي المختلفة.
الوحدات الرئيسية للمحطة التجريبية
وحدات المعالجة الأولية والتناضح العكسي
وحدات تعظيم الفائدة من الرجيع الملحي
وحدات الطاقة المتجددة والنظيفة
وحدات التقنية المتقدمة
وحدة الفلترة ثنائية الوسائط(DMF)
الهدف الرئيسي من استخدام الفلاتر ثنائية الوسائط (DMF) هو تقليل مؤشر كثافة الرواسب (SDI) قبل أن تنتقل مياه البحر إلى وحدة التحلية العكسية (RO).
تحتوي مياه البحر عادةً على مواد عالقة كلية (TSS) يمكن أن تؤثر سلبًا على عملية التحلية بالأغشية. وتشمل هذه المواد العالقة جزيئات دقيقة مثل: الطمي، الطين، الرمل، المواد العضوية، الطحالب، والكائنات الدقيقة الأخرى.
من خلال إزالة هذه المواد العالقة، يتم تقليل فرق الضغط العالي وضمان فعالية المعدات التالية في سلسلة المعالجة، مثل الفلاتر الدقيقة وأغشية التحلية العكسية.
سنة التشغيل 2023 - الطاقة الاستيعابية 100 م³/ساعة
وحدات التناضح العكسي
يشير مصطلح RO إلى "التناضح العكسي"، وهو عملية ترشيح تتم بعكس اتجاه الضغط الأسموزي.
تعمل أغشية التناضح العكسي كمنخل جزيئي، حيث تزيل ما يصل إلى 99.5٪ من المواد الصلبة، والميكروبات، والجزيئات الصغيرة، والمركبات العضوية ذات الأوزان الجزيئية الأكبر من 300 ميكرون، أو الجزيئات التي يزيد حجمها عن 0.001 ميكرون.
يُستخدم غشاء شبه نفاذ للفصل بين جزيئات الماء والمواد الأخرى المذابة أو المعلقة، وذلك من خلال تطبيق ضغط أعلى من الضغط الأسموزي.
سنة التشغيل 2011 - السعة 10 م3/ساعة
وحدة الترشيح النانوية 1
تُصنّف أغشية الترشيح بالنانو (NF) على أنها تقنية تعتمد على الضغط، وتقع من حيث حجم المسام بين أغشية التحلية العكسية (RO) وأغشية الترشيح الفائق (UF).
يبلغ حجم المسام فيها ما بين 0.1 إلى 1 نانومتر، وتتميز بحد فصل الوزن الجزيئي (MWCO) يتراوح بين 200 إلى 1000 دالتون.
تم اعتماد تقنية الترشيح بالنانو واستخدامها على نطاق واسع في تطبيقات التحلية، نظرًا لأدائها المتميز في إزالة المركبات العضوية والبكتيريا من المياه.
علاوة على ذلك، فإن قدرة NF على فصل الأيونات الثنائية من مياه البحر تُعد من المميزات الأساسية في عمليات استخراج المعادن من الرجيع الملحي.
سنة التشغيل 2010 - السعة 20 م3/ساعة', N'المحطات التجريبية', N'استكشف المختبرات والمحطات التجريبية في معهد ابتكار تقنيات المياه والأبحاث، حيث يتم التركيز على معالجة المياه وتحلية المياه وتطوير التقنيات المتقدمة.', 'ar', NULL)
GO
INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-7bb2-9dfb-e0f5de9d2c14', N'019fa37a-8e57-77da-87ce-720a22ad1688', N'تحليــة الميــاه​', N'تنظُر المملكة العربية السعودية إلى البحر بوصفه موردًا إستراتيجيًّا للمياه المحلاة، فمنذ أن بدأت فكرة استثماره لتأمين حاجتها من الإمداد المائي، ما تزال المملك...', N'تحليــة الميــاه​
تنظُر المملكة العربية السعودية إلى البحر بوصفه موردًا إستراتيجيًّا للمياه المحلاة، فمنذ أن بدأت فكرة استثماره لتأمين حاجتها من الإمداد المائي، ما تزال المملكة تتبوأ مركز الريادة في إنتاج المياه المحلاة، حتى أصبحت اليوم أكبر منتج للمياه المحلاة في العالم، بطاقةٍ يومية تتجاوز 11.1 مليون متر مكعب، نتيجة لعقود من العمل، والتطوير، والرهان على الابتكار.​ وتعمل "تحلية المياه" الذراع التشغيلي المرحلي للهيئة السعودية للمياه على تأمين الإمداد المائي للمملكة، من خلال تشغيل وصيانة منظومات التحلية الحديثة على السواحل الشرقية والغربية لتحلية مياه البحر، إلى جانب تطوير منظومات تحلية المياه الجوفية والسطحية، مستندة إلى خبرة تقنية رائدة تجاوزت نصف قرن، وإرادة وطنية من أولوياتها الاستدامة والابتكار.​ وسجّلت المملكة قفزات نوعية في صناعة التحلية، تعدت حجم الإنتاج إلى تعزيز الكفاءة، والتقنيات المبتكرة، فيما استطاعت "تحلية المياه" أن تحقّق إنجازًا فريدًا من خلال إنتاج كميات مياه أكثر باستهلاك طاقةٍ أقل، وتكلفة تشغيلية منخفضة.​ وتبرز "تحلية المياه" ضمن منظومة المياه في المملكة التي تعدُّ ركيزة استراتيجية لرؤية السعودية 2030، وشاهدًا على قدرة السعودية في تطويع التحديات البيئية والهندسية لخدمة الإنسان والتنمية، وابتكار نموذج يحتذى به في إدارة الموارد الطبيعية على المستوى العالمي.​
الأدوار
تحلية مياه البحر والمياه الجوفية وتنقية مياه السدود.
إيصال المياه المحلاة المنتجة لمختلف مناطق المملكة العربية السعودية.
الرؤية
الريادة والتميز عالمياً في صناعة تحلية المياه.​
الرسالة
تلبية احتياجات عملائنا من المياه المحلاة بكفاءة وموثوقية، وبأقل تكلفة ممكنة وأعلى مردود​ اقتصادي، والاستثمار الفعال في مواردنا البشرية، وتحفيزها، وتطوير صناعة التحلية، والمساهمة في​ التنمية الاقتصادية والاجتماعية، والالتزام بمعايير السلامة والبيئة.​
القيم
الجودة
التمكين
الاستدامة
الابتكار
السلامة
الأهداف
تطبيق أعلى معايير السلامة والبيئة والصحة المهنية​
الاستثمار الأمثل لرأس المال البشري​
رفع الكفاء التشغيلية وتحسين إدارة العمليات​
الامتثال لمعايير جودة المياه القياسية المعتمدة​
أمن إمدادات المياه​
الاستدامة المالية​
لزيارة الموقع', N'تحليــة الميــاه​', N'تنظُر المملكة العربية السعودية إلى البحر بوصفه موردًا إستراتيجيًّا للمياه المحلاة، فمنذ أن بدأت فكرة استثماره لتأمين حاجتها من الإمداد المائي، ما تزال المملك...', 'ar', NULL)
GO
