INSERT [dbo].[PageTranslations] ([Id], [PageId], [Title], [Summary], [Body], [SeoTitle], [SeoDescription], [Language], [Sections]) VALUES (N'019fa37a-8e57-788a-a2f4-f0348b631b58', N'019fa37a-8e57-7201-9df5-6abf16bfc1dc', N'شركة المياه الوطنية', N'شركة مساهمة سعودية مملوكة بالكامل للدولة متمثلة في صندوق الاستثمارات العامة، أُسست عام 2008م وتختص في تقديم خدمات المياه والصرف الصحي، وفق أحدث المعايير العا...', N'شركة المياه الوطنية
شركة المياه الوطنية (شركة مساهمة سعودية، مملوكة بالكامل للدولة متمثلة في صندوق الاستثمارات العامة)، تأسست عام 2008، تقدّم خدمات المياه والصرف الصحي على أسس تجارية سليمة وفقًا لأحدث المعايير العالمية.
الأدوار
تقديم خدمات المياه والصرف الصحي وفقًا لأحدث المعايير العالمية.
ربط جميع العملاء بشبكات المياه والصرف الصحي.
الحفاظ على موارد المياه الطبيعية وحماية البيئة.
الرؤية
تقديم خدمات مياه مستدامة ذات جودة عالية في كافة مناطق المملكة؛ لتحسين جودة الحياة اليوم، وفي المستقبل.​
الرسالة
نسـعى إلى توفير المـياه وخـدماتها، وتحـسين مـستوى الـجودة في جـميع أنحاء المملـكة بالتعاون مع شركائنا من خلال رفع الكفاءة، والفعالية، وتحقيق الاستدامة المالية.​
القيم
العميل أولًا
الاحترام المتبادل
الشفافية
الالتزام
الابتكار
الأهداف
تحســين جــودة خدمــات الميــاه
توســيع شــبكات الميــاه والصــرف الصحــي
خفض الأثر البيئي الناتج عن عملياتنــا
لزيارة الموقع', N'شركة المياه الوطنية', N'شركة مساهمة سعودية مملوكة بالكامل للدولة متمثلة في صندوق الاستثمارات العامة، أُسست عام 2008م وتختص في تقديم خدمات المياه والصرف الصحي، وفق أحدث المعايير العا...', 'ar', NULL)
