INSERT [dbo].[FaqTranslations] ([Id], [FaqId], [Question], [Answer], [Language]) VALUES (N'019fa37a-bb11-76d9-98bf-ea44cf9db2cf', N'019fa37a-bb11-7f53-9993-953431acd812', N'Is the beneficiary entitled to request exemption from bills in the event of increased bills due to hidden leaks within the property?', N'You may request an exemption of 50% of the value of the increased bill resulting from hidden leaks by following these steps:
