INSERT [dbo].[FaqTranslations] ([Id], [FaqId], [Question], [Answer], [Language]) VALUES (N'019fa37a-bb0f-746e-aab7-ff1402479ad7', N'019fa37a-bb0f-7bfb-9dc3-72d58d44f679', N'ماهي أنواع الكروت التشغيلية التي تقبلها الهيئة؟', N'تجدون أدناه تفصيل الكروت التشغيلية التي تقبلها الهيئة حسب النشاط (مخصص للبيع / غير مخصص للبيع):
أنواع الكروت التشغيلية المخصصة للبيع:
يشترط أن تكون الكروت التشغيلية المخصصة للبيع جميعها مخصصة للنقل عام.
إذا كان مقدم الطلب منشأة، لابد أن يكون كرت التشغيل مخصصًا للنقل الثقيل للبضائع لأغراض تجارية (للغير - منشآت).
إذا كان مقدم الطلب فردًا، لابد أن يكون كرت التشغيل مخصصًا للنقل الثقيل للبضائع لأغراض تجارية (للغير – أفراد).
أنواع الكروت التشغيلية للصهاريج غير المخصصة للبيع:
إذا كان مقدم الطلب منشأة (نقل عام)، لابد أن يكون كرت التشغيل مخصصًا للنقل الثقيل للبضائع لأغراض تجارية (لصالح المنشأة).
إذا كان مقدم الطلب منشأة (نقل خاص)، لابد أن يكون كرت التشغيل مخصصًا للنقل الثقيل للبضائع لأغراض غير تجارية.', 'ar')
GO
