INSERT [dbo].[ServiceTranslations] ([Id], [ServiceId], [Name], [Description], [Fee], [DeliveryTime], [RequiredDocuments], [Steps], [Terms], [Objectives], [StartServiceUrl], [GuideFileId], [Language]) VALUES (N'019fa37a-acbe-7b5a-a539-734c86f3d161', N'019fa37a-acbe-7cc9-9507-54a07ec09ac3', N'معالجة مياه الصرف الصحي', N'إنشاء وتشغيل محطة معالجة مياه صرف صحي محددة الموقع، وبيع المياه المعالجة المنتجة من المحطة بالجملة، ولا يشمل ذلك إنشاء وتشغيل محطات معالجة مياه الصرف الصناعي، ومحطات​ المعالجة الخاصة، أو المدمجة.​.', N'بناءً على حجم النشاط', N'15 يومًا', NULL, NULL, NULL, NULL, N'https://e-services.swa.gov.sa/', NULL, 'ar')
GO
INSERT [dbo].[ServiceTranslations] ([Id], [ServiceId], [Name], [Description], [Fee], [DeliveryTime], [RequiredDocuments], [Steps], [Terms], [Objectives], [StartServiceUrl], [GuideFileId], [Language]) VALUES (N'019fa37a-b361-784d-bcd5-7b2ff90160d7', N'019fa37a-b273-7571-a00c-5fe7de3c5a3b', N'توزيع المياه المحلاة والمنقاة', N'إنشاء وتشغيل منشآت وشبكات وصهاريج -ضمن نطاق مكاني محدد- لتوزيع المياه على المستهلكين؛ للاستخدام الحضري، أو الصناعي، ويشمل شراء​ المياه المحلاة والمنقاة بالجملة، وضخ​ المياه الصالحة للشرب من خلال محطات مدمجة، ولا يشمل​ توزيع المياه المعالجة، أو بيعها​ بالتجزئة.', N'بناءً على حجم النشاط', N'15 يومًا', NULL, NULL, NULL, NULL, N'https://e-services.swa.gov.sa/', N'019fa37a-b361-78b2-92ac-c0480f19d293', 'ar')
GO
INSERT [dbo].[ServiceTranslations] ([Id], [ServiceId], [Name], [Description], [Fee], [DeliveryTime], [RequiredDocuments], [Steps], [Terms], [Objectives], [StartServiceUrl], [GuideFileId], [Language]) VALUES (N'019fa37a-a31d-77fe-aa3b-8287a9a8060a', N'019fa37a-a31d-79c5-bdae-eeb3c4a8b3b3', N'Document Status Inquiry', N'The Document Status Inquiry Service in the Water Sector empowers individuals and organizations to seamlessly track the status of their transactions with transparency and ease. The service provides comprehensive insights into the various stages of the process, along with detailed information designed to enhance response efficiency and drive greater operational effectiveness.
Required Information
Enter your National ID or Iqama number (10 digits) and verify through Nafath
Enter the document number
Provide the document created year (e.g., 2023 or 1445)', N'Free', N'Immediate Inquiry', NULL, NULL, NULL, NULL, N'https://www.swa.gov.sa/en/services/request-service/request-transaction-inquiry/transaction-inquiry', NULL, 'en')
GO
INSERT [dbo].[ServiceTranslations] ([Id], [ServiceId], [Name], [Description], [Fee], [DeliveryTime], [RequiredDocuments], [Steps], [Terms], [Objectives], [StartServiceUrl], [GuideFileId], [Language]) VALUES (N'019fa37a-b6a9-7e3d-9699-8728f0a3d632', N'019fa37a-b515-75b2-9326-da888cbd8abd', N'الخزن الإستراتيجي', N'إنشاء وتشغيل منشآت وخزانات -في نطاق مكاني محدد- لتخزين المياه لغايات استخدامها في حالات طوارئ الإمداد، ولا يشمل خزن​ المياه في الطبقات الجوفية، أو السدود، أو ​ خزن المياه لغرض غير ضمان استقرار الإمداد.', N'بناءً على حجم النشاط', N'15 يومًا', NULL, NULL, NULL, NULL, N'https://e-services.swa.gov.sa/ar/auth/login', N'019fa37a-b6a8-7ebf-aaa7-d35c43d07350', 'ar')
GO
INSERT [dbo].[ServiceTranslations] ([Id], [ServiceId], [Name], [Description], [Fee], [DeliveryTime], [RequiredDocuments], [Steps], [Terms], [Objectives], [StartServiceUrl], [GuideFileId], [Language]) VALUES (N'019fa37a-a31d-7528-8616-8f8bd51d3c29', N'019fa37a-a31d-79c5-bdae-eeb3c4a8b3b3', N'الاستعلام عن المعاملات', N'تتيح خدمة الاستعلام عن المعاملات بقطاع المياه للأفراد والمؤسسات متابعة حالة معاملاتهم بكل سهولة وشفافية، بما في ذلك تفاصيل المراحل التي مرت بها ومعلومات إضافية تسهم في تسريع عملية الاستجابة وتحقيق الكفاءة.
المعلومات المطلوبة
ادخل رقم الهوية / الإقامة (10 أرقام) وقم بالتسجيل عبر نفاذ
ادخل رقم الوارد
قم بإدخال تاريخ المعاملة (مثل: 2023 أو 1445)', N'مجانًا', N'استعلام فوري', NULL, NULL, NULL, NULL, N'https://www.swa.gov.sa/ar/services/request-service/request-transaction-inquiry/transaction-inquiry', NULL, 'ar')
GO
